#!/usr/bin/env node

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { extractFunctionExports } from './lib/api-snapshot-parse.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const snapshot = readFileSync(path.join(ROOT, 'docs/api/docx-editor-vue/index.api.md'), 'utf8');
const outputPath = path.join(ROOT, 'packages/nuxt/src/vue-composables.generated.ts');
const expected = [...extractFunctionExports(snapshot).keys()]
  .filter((name) => /^use[A-Z]/.test(name))
  .sort();
const generated = [
  '// Generated by scripts/check-nuxt-auto-imports.mjs --write. Do not edit.',
  'export const VUE_COMPOSABLES = [',
  ...expected.map((name) => `  '${name}',`),
  '] as const;',
  '',
].join('\n');

if (process.argv.includes('--write')) {
  writeFileSync(outputPath, generated);
  console.log(`✓ Generated ${expected.length} Nuxt auto-imports from Vue exports`);
  process.exit(0);
}

if (readFileSync(outputPath, 'utf8') !== generated) {
  console.error('Nuxt auto-imports drifted from Vue exports');
  console.error('Fix: bun run generate:nuxt-auto-imports');
  process.exit(1);
}

console.log(`✓ Nuxt auto-imports: ${expected.length} generated Vue composables matched`);
